package com.example.starter.support;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HexFormat;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

/**
 * 幂等指纹：覆盖 requestId 与全部业务字段，字段按名字典序规范化后做 SHA-256。
 *
 * <p>不依赖 Jackson 的时间模块：标量统一 {@code String.valueOf}（Instant 取其 ISO-8601 文本），
 * 因此同一业务参数集合在任何进程下指纹一致，可复算。</p>
 */
public final class Fingerprints {

    private Fingerprints() {
    }

    public static String sha256(Map<String, Object> fields) {
        TreeMap<String, Object> sorted = new TreeMap<>(fields);
        String canonical = canonical(sorted);
        return sha256Utf8(canonical);
    }

    public static String sha256Utf8(String text) {
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            return HexFormat.of().formatHex(digest.digest(text.getBytes(StandardCharsets.UTF_8)));
        } catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException("指纹计算失败", e);
        }
    }

    @SuppressWarnings("unchecked")
    private static String canonical(Object value) {
        if (value == null) {
            return "null";
        }
        if (value instanceof Map<?, ?> map) {
            StringBuilder sb = new StringBuilder("{");
            TreeMap<String, Object> byKey = new TreeMap<>();
            map.forEach((k, v) -> byKey.put(String.valueOf(k), v));
            boolean first = true;
            for (Map.Entry<String, Object> e : byKey.entrySet()) {
                if (!first) {
                    sb.append(',');
                }
                first = false;
                sb.append(e.getKey()).append('=').append(canonical(e.getValue()));
            }
            return sb.append('}').toString();
        }
        if (value instanceof List<?> list) {
            StringBuilder sb = new StringBuilder("[");
            for (int i = 0; i < list.size(); i++) {
                if (i > 0) {
                    sb.append(',');
                }
                sb.append(canonical(list.get(i)));
            }
            return sb.append(']').toString();
        }
        return value.getClass().getSimpleName() + "(" + value + ")";
    }
}

package com.example.starter.web.dto;

import jakarta.validation.constraints.NotBlank;

import java.time.Instant;

/**
 * 出水登记请求，出水后进入 2 小时观察期。
 *
 * @param requestId     本次操作的幂等键
 * @param diveRequestId 所属潜次 requestId
 * @param surfacedAt    出水时刻（UTC）；为空取服务时钟
 */
public record SurfaceRequest(
        @NotBlank String requestId,
        @NotBlank String diveRequestId,
        Instant surfacedAt) {
}

package com.example.starter.web.dto;

import java.util.List;

/**
 * 作业申请受理结果。
 */
public record ApplyResult(
        String requestId,
        String teamKey,
        String diverACode,
        String diverBCode,
        int plannedDepthM,
        int plannedBottomMin,
        String status,
        boolean replayed) {

    public record Segment(String phase, int fromDepthM, int toDepthM, int durationMin,
                          int rateLimitMMin) {
    }

    /** 减压方案结果；profile 为可复算的分段剖面。 */
    public record PlanResult(
            String requestId,
            int version,
            int depthM,
            int bottomMin,
            int ndlLimitMin,
            int rateLimitMMin,
            List<Segment> profile,
            int frozenOldVersions,
            boolean replayed) {
    }

    /** 水下记录结果；effective=FALSE 表示单人记录尚未成对生效。 */
    public record RecordResult(
            String requestId,
            int planVersion,
            String diverCode,
            String phase,
            String rateMMin,
            boolean speedAlert,
            boolean effective,
            String pairedWith,
            String status,
            int cumulativeBottomMin24h,
            boolean replayed) {
    }

    public record SurfaceResult(
            String requestId,
            String surfacedAtUtc,
            String observationDueAtUtc,
            String status,
            boolean replayed) {
    }

    public record VitalsResult(
            String requestId,
            String status,
            boolean symptomatic,
            boolean chamberProtocolStarted,
            boolean lateVitals,
            boolean replayed) {
    }

    public record CloseResult(
