 * @param bottomMin     方案底时间，分钟（不得超过该深度免减压极限，恰在极限合法）
 */
public record PlanRequest(
        @NotBlank String requestId,
        @NotBlank String diveRequestId,
        @Positive int depthM,
        @Positive int bottomMin) {
